import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const container=document.getElementById('game');
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5b0');scene.fog=new THREE.FogExp2('#a9c5b0',.0085);
const camera=new THREE.PerspectiveCamera(57,innerWidth/innerHeight,.1,220);
const renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;renderer.outputColorSpace=THREE.SRGBColorSpace;container.appendChild(renderer.domElement);
scene.add(new THREE.HemisphereLight('#e4f0e2','#4e6042',2.05));
const sun=new THREE.DirectionalLight('#fff0d0',3.3);sun.position.set(-32,55,26);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-58;sun.shadow.camera.right=58;sun.shadow.camera.top=58;sun.shadow.camera.bottom=-58;sun.shadow.bias=-.00025;scene.add(sun);
const fill=new THREE.DirectionalLight('#bddde7',.8);fill.position.set(30,18,-35);scene.add(fill);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const M={grass:mat('#79965e'),darkGrass:mat('#5f7848'),leaf:mat('#47724a'),leaf2:mat('#6a8b51'),bark:mat('#5d4530'),stone:mat('#968c76'),stoneLight:mat('#b0a58b'),rock:mat('#696e5f'),iron:mat('#38433a',.6,.25),wood:mat('#76573a'),cream:mat('#e8debd'),water: new THREE.MeshPhysicalMaterial({color:'#3c9694',roughness:.2,metalness:.1,transparent:true,opacity:.85,clearcoat:1}),gold:mat('#c99e56',.5,.15)};
function mesh(g,m,parent=scene){const o=new THREE.Mesh(g,m);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o}
function box(parent,x,y,z,sx,sy,sz,m,r=0){const o=mesh(new THREE.BoxGeometry(sx,sy,sz),m,parent);o.position.set(x,y,z);o.rotation.y=r;return o}
function ell(parent,x,y,z,sx,sy,sz,m,rx=0,ry=0,rz=0){const o=mesh(new THREE.SphereGeometry(1,18,14),m,parent);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.rotation.set(rx,ry,rz);return o}
function cylinder(parent,x,y,z,rt,rb,h,m,seg=12){const o=mesh(new THREE.CylinderGeometry(rt,rb,h,seg),m,parent);o.position.set(x,y,z);return o}
function group(parent=scene,x=0,y=0,z=0){const g=new THREE.Group();g.position.set(x,y,z);parent.add(g);return g}
function randFactory(seed){let s=seed>>>0;return()=>{s=(s*1664525+1013904223)>>>0;return s/4294967296}}
const rand=randFactory(6241);
// Procedural ground with fine color variation.
const groundGeo=new THREE.PlaneGeometry(130,130,1,1);groundGeo.rotateX(-Math.PI/2);const ground=mesh(groundGeo,M.grass);ground.position.y=-.12;ground.receiveShadow=true;
function makeTexture(base,spots,count=900){const c=document.createElement('canvas');c.width=c.height=512;const ctx=c.getContext('2d');ctx.fillStyle=base;ctx.fillRect(0,0,512,512);for(let i=0;i<count;i++){ctx.globalAlpha=.08+rand()*.19;ctx.fillStyle=spots[Math.floor(rand()*spots.length)];const x=rand()*512,y=rand()*512,r=rand()*4+1;ctx.beginPath();ctx.ellipse(x,y,r*1.6,r,rand()*3,0,Math.PI*2);ctx.fill()}ctx.globalAlpha=1;const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.repeat.set(28,28);t.colorSpace=THREE.SRGBColorSpace;return t}
M.grass.map=makeTexture('#7f9d66',['#3f693f','#d3c887','#65864b','#a8b578'],1800);M.grass.needsUpdate=true;
const stoneTex=makeTexture('#9c927e',['#c4b99e','#706958','#ddd0b1','#877d6a'],420);stoneTex.repeat.set(3.2,3.2);const pathMat=new THREE.MeshStandardMaterial({map:stoneTex,color:'#e2d9c0',roughness:.95});
function ribbon(points,width,material=pathMat){const curve=new THREE.CatmullRomCurve3(points.map(p=>new THREE.Vector3(p[0],.035,p[1])));const steps=Math.max(24,points.length*12),verts=[],uv=[],idx=[];for(let i=0;i<=steps;i++){const t=i/steps,p=curve.getPoint(t),tan=curve.getTangent(t),nx=-tan.z,nz=tan.x;verts.push(p.x+nx*width/2,p.y,p.z+nz*width/2,p.x-nx*width/2,p.y,p.z-nz*width/2);uv.push(0,t*12,1,t*12);if(i<steps){const n=i*2;idx.push(n,n+1,n+2,n+1,n+3,n+2)}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(verts,3));g.setAttribute('uv',new THREE.Float32BufferAttribute(uv,2));g.setIndex(idx);g.computeVertexNormals();const o=mesh(g,material);o.castShadow=false;return o}
// Central promenade and branching paths.
ribbon([[-3,42],[-3,28],[-1,17],[0,8],[0,-5],[2,-17],[0,-29],[2,-42]],6.5);
ribbon([[-42,2],[-29,2],[-18,1],[-8,0],[4,0],[17,0],[29,-1],[42,-2]],6.5);
ribbon([[-29,1],[-30,-8],[-29,-17],[-27,-27]],4.1);ribbon([[29,-1],[30,-10],[29,-19],[27,-27]],4.1);
ribbon([[-1,-28],[-12,-30],[-21,-30],[-28,-27]],4);ribbon([[2,-29],[12,-31],[21,-30],[28,-27]],4);
ribbon([[-1,28],[-13,30],[-22,29],[-28,27]],4);ribbon([[1,28],[13,30],[22,29],[28,27]],4);
// Entry plaza, low perimeter wall and warm lanterns.
const plaza=mesh(new THREE.CircleGeometry(10,64),pathMat);plaza.rotation.x=-Math.PI/2;plaza.position.set(0,.04,0);plaza.receiveShadow=true;
const fountain=group(scene,0,0,0);cylinder(fountain,0,.17,0,2.1,2.2,.34,M.stoneLight,32);cylinder(fountain,0,.39,0,1.5,1.7,.12,M.water,32);cylinder(fountain,0,.7,0,.35,.48,.65,M.stone,16);ell(fountain,0,1.12,0,.18,.5,.18,M.water);
for(let i=0;i<8;i++){const a=i*Math.PI/4;const l=group(scene,Math.cos(a)*8.8,.0,Math.sin(a)*8.8);cylinder(l,0,.75,0,.12,.17,1.5,M.wood);ell(l,0,1.6,0,.32,.38,.32,M.gold);ell(l,0,1.63,0,.2,.26,.2,mat('#fff1bd',.25));}
// Forest planting: scattered shrubs, ornamental trees and flowers.
function tree(x,z,size=1,kind=Math.floor(rand()*3)){const g=group(scene,x,0,z);const trunk=cylinder(g,0,size*1.1,0,size*.14,size*.23,size*2.2,M.bark,9);trunk.rotation.z=(rand()-.5)*.11;if(kind===0){for(let i=0;i<4;i++){const y=size*(1.6+i*.55),r=size*(1.05-i*.13);const c=mesh(new THREE.ConeGeometry(r,size*1.05,9),i%2?M.leaf:M.leaf2,g);c.position.set((rand()-.5)*.3,y,(rand()-.5)*.3)}}else{for(let i=0;i<6;i++){const ang=i*1.05, y=size*(2.5+(rand()-.5)*.7),r=size*(.55+rand()*.35);ell(g,Math.cos(ang)*size*.46,y,Math.sin(ang)*size*.42,r,r*.75,r,M.leaf2,0,rand()*2,0);ell(g,Math.cos(ang)*size*.46+.1,y+.22*size,Math.sin(ang)*size*.42,r*.72,r*.78,r*.78,M.leaf)} }return g}
for(let i=0;i<170;i++){const x=(rand()-.5)*104,z=(rand()-.5)*104;if(Math.abs(x)<13&&Math.abs(z)<13)continue;let near=false;for(const h of [[-28,-27],[28,-27],[-28,27],[28,27],[-34,0],[34,0],[0,-37],[0,37]])if(Math.abs(x-h[0])<12&&Math.abs(z-h[1])<11){near=true;break}if(!near&&rand()<.25)tree(x,z,.65+rand()*.9,Math.floor(rand()*3));else if(!near){const s=group(scene,x,0,z);for(let j=0;j<3;j++)ell(s,(rand()-.5)*1.3,.35+rand()*.18,(rand()-.5)*1.1,.55,.42,.55,j%2?M.leaf:M.leaf2)}}
// Rock clusters and flowers scattered beside paths.
for(let i=0;i<100;i++){const x=(rand()-.5)*85,z=(rand()-.5)*85;if(Math.abs(x)<6&&Math.abs(z)<6)continue;const r=.12+rand()*.34;const o=ell(scene,x,r*.38,z,r*1.5,r*.72,r,M.rock,rand()*.3,rand()*3,rand()*.3);o.castShadow=true}
const flowers=['#e8c978','#f2d9bc','#d98463'];for(let i=0;i<140;i++){let x=(rand()-.5)*88,z=(rand()-.5)*88;if(Math.abs(x)<5||Math.abs(z)<5)continue;const g=group(scene,x,0,z);cylinder(g,0,.19,0,.025,.02,.38,M.leaf,6);ell(g,0,.4,0,.12,.1,.12,mat(flowers[i%3]),0,0,0)}

const enclosures=[
 {name:'Elephant Valley',species:'African elephant',icon:'🐘',x:-29,z:-28,w:18,d:16,color:'#8b9290',decor:'savanna',fact:'Elephants greet each other with their trunks—and can recognize friends after years apart.'},
 {name:'Rhino Ridge',species:'White rhinoceros',icon:'🦏',x:29,z:-28,w:18,d:16,color:'#85857b',decor:'ridge',fact:'A rhino’s horn is made of keratin, the same material as your hair and fingernails.'},
 {name:'Hippo Lagoon',species:'Pygmy hippopotamus',icon:'🦛',x:0,z:-42,w:20,d:13,color:'#77736e',decor:'lagoon',fact:'Hippos spend much of the day in water, where their dense bodies feel almost weightless.'},
 {name:'Tiger Forest',species:'Bengal tiger',icon:'🐅',x:-36,z:0,w:16,d:19,color:'#d18a3d',decor:'jungle',fact:'Every tiger has a unique stripe pattern—like a fingerprint hidden in the forest.'},
 {name:'Lion Lookout',species:'African lion',icon:'🦁',x:36,z:0,w:16,d:19,color:'#b18a4d',decor:'savanna',fact:'A lion’s roar can travel up to five miles across open country.'},
 {name:'Jaguar Falls',species:'Jaguar',icon:'🐆',x:-29,z:28,w:18,d:16,color:'#bd924b',decor:'falls',fact:'Jaguars are powerful swimmers and use their strong jaws to crack turtle shells.'},
 {name:'Wolfwood',species:'Gray wolf',icon:'🐺',x:29,z:28,w:18,d:16,color:'#777a70',decor:'forest',fact:'A wolf pack is a family, working together to care for pups and find food.'},
 {name:'Bear Creek',species:'Brown bear',icon:'🐻',x:0,z:42,w:20,d:13,color:'#80604a',decor:'creek',fact:'Brown bears have an incredible sense of smell—many times stronger than ours.'}
];
const animalAnim=[];
function makeAnimal(kind,x,z,scale=1){const root=group(scene,x,.25,z);root.scale.setScalar(scale);const coat=mat(({elephant:'#878d89',rhino:'#85837a',hippo:'#77727a',tiger:'#d28a3c',lion:'#c9954e',jaguar:'#d4a84e',wolf:'#85867e',bear:'#76563f'})[kind]);const dark=mat('#292b28'),belly=mat(({elephant:'#a2a49b',rhino:'#a19b8d',hippo:'#92858b',tiger:'#f0d7b4',lion:'#d8bd8c',jaguar:'#f4d791',wolf:'#d0cbbb',bear:'#b28c67'})[kind]);const eye=mat('#241d17',.28);const motion=group(root);animalAnim.push({motion,phase:rand()*6.28,kind});
 const bodySize=kind==='elephant'?[1.02,.92,1.42]:kind==='hippo'?[1.04,.78,1.25]:[.78,.67,1.25];ell(motion,0,1.32,0,...bodySize,coat,0,0,0);
 const headZ=kind==='elephant'?-1.07:-1.08;ell(motion,0,1.58,headZ,kind==='elephant'?.72:.58,kind==='hippo'?.61:.56,.61,coat,0,0,0);
 // Four sturdy legs with softly rounded joints.
 const legXs=kind==='elephant'?.66:.51,legZs=.82;for(const sx of [-1,1])for(const sz of [-1,1]){const leg=ell(motion,sx*legXs,.56,sz*legZs,kind==='elephant'?.26:.2,kind==='elephant'?.57:.48,.24,coat);leg.rotation.z=sx*.025;ell(motion,sx*legXs,.2,sz*legZs-.04,.27,.15,.32,coat)}
 // Eyes, ears and species-defining details.
 for(const side of [-1,1])ell(motion,side*.37,1.78,-1.47,.075,.09,.045,eye);
 if(kind==='elephant'){for(const side of [-1,1]){ell(motion,side*.66,1.62,-1.18,.38,.53,.14,coat,0,0,side*.22);const tusk=mesh(new THREE.ConeGeometry(.12,.72,12),mat('#eee2be'),motion);tusk.position.set(side*.38,1.25,-1.73);tusk.rotation.x=-.48;tusk.rotation.z=side*-.22}const trunk= new THREE.CatmullRomCurve3([new THREE.Vector3(0,1.52,-1.57),new THREE.Vector3(0,1.1,-1.82),new THREE.Vector3(.05,.75,-1.79),new THREE.Vector3(.18,.69,-1.61)]);mesh(new THREE.TubeGeometry(trunk,18,.16,10,false),coat,motion);}
 if(kind==='rhino'){const horn=mesh(new THREE.ConeGeometry(.2,.72,10),mat('#ded3b6'),motion);horn.position.set(0,1.96,-1.56);horn.rotation.x=-.38;const h2=mesh(new THREE.ConeGeometry(.13,.38,10),mat('#d1c5a6'),motion);h2.position.set(0,1.87,-1.27);h2.rotation.x=-.3;for(const s of [-1,1])ell(motion,s*.42,2.01,-1.15,.16,.27,.12,coat,0,0,s*.3)}
 if(kind==='hippo'){ell(motion,0,1.3,-1.57,.57,.37,.45,coat);for(const s of [-1,1])ell(motion,s*.44,2.02,-1.16,.16,.18,.13,coat);ell(motion,0,1.08,-1.91,.37,.08,.08,dark)}
 if(kind==='tiger'||kind==='jaguar'){for(const side of [-1,1]){for(let i=0;i<7;i++){const zz=-.82+i*.28;const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(side*.74,1.83,zz),new THREE.Vector3(side*.84,1.55,zz+.05),new THREE.Vector3(side*.76,1.22,zz+.1)]);mesh(new THREE.TubeGeometry(curve,6,kind==='tiger'?.055:.043,5,false),kind==='tiger'?dark:mat('#513c22'),motion)}}if(kind==='jaguar'){for(let i=0;i<14;i++){const s=i%2?1:-1;const zz=-.87+(i%7)*.28;ell(motion,s*.77,1.57,zz,.07,.07,.045,mat('#2a2922'))}}}
 if(kind==='lion'){ell(motion,0,1.65,-1.12,.8,.82,.6,mat('#845831'));ell(motion,0,1.64,-1.47,.5,.5,.39,mat('#c2914c'));ell(motion,0,1.41,-1.79,.31,.2,.17,belly);for(let i=0;i<10;i++){let a=i*Math.PI/5;ell(motion,Math.cos(a)*.62,1.65+Math.sin(a)*.6,-1.42,.16,.28,.14,mat('#785031'),0,0,a)}}
 if(kind==='wolf'){for(const s of [-1,1]){const e=mesh(new THREE.ConeGeometry(.2,.58,8),coat,motion);e.position.set(s*.36,2.1,-1.04);e.rotation.z=s*-.22}ell(motion,0,1.43,-1.55,.37,.28,.4,belly)}
 if(kind==='bear'){for(const s of [-1,1])ell(motion,s*.4,2.02,-1.12,.21,.23,.16,coat);ell(motion,0,1.39,-1.58,.42,.3,.38,belly);ell(motion,0,1.55,-1.91,.19,.12,.15,dark)}
 // Tail curls behind the silhouette.
 if(!['hippo','elephant','rhino'].includes(kind)){const tail=new THREE.CatmullRomCurve3([new THREE.Vector3(0,1.28,1.05),new THREE.Vector3(.12,1.05,1.43),new THREE.Vector3(.1,.98,1.7)]);mesh(new THREE.TubeGeometry(tail,10,.07,6,false),coat,motion);ell(motion,.1,.97,1.7,.1,.11,.11,kind==='tiger'?dark:coat)}
 return root;
}
function sign(parent,x,z,title,subtitle){const postMat=mat('#64492f');cylinder(parent,x,.85,z,.055,.07,1.7,postMat,8);box(parent,x,1.68,z,.95,.55,.12,mat('#273e32'),0);box(parent,x,1.68,z-.075,.84,.39,.025,mat('#b9a171'),0); // inset sign face
 const canvas=document.createElement('canvas');canvas.width=512;canvas.height=192;const c=canvas.getContext('2d');c.fillStyle='#213b30';c.fillRect(0,0,512,192);c.fillStyle='#e7d9b8';c.font='bold 34px Georgia';c.fillText(title.toUpperCase(),24,76);c.fillStyle='#c9b986';c.font='25px sans-serif';c.fillText(subtitle,24,130);const tex=new THREE.CanvasTexture(canvas);tex.colorSpace=THREE.SRGBColorSpace;const plaque=mesh(new THREE.PlaneGeometry(.82,.31),new THREE.MeshBasicMaterial({map:tex}),parent);plaque.position.set(x,1.68,z-.096);}
function pool(parent,x,z,w,d){const rim=mesh(new THREE.CylinderGeometry(1,1,.28,40),M.stone,parent);rim.scale.set(w/2,.14,d/2);rim.position.set(x,.16,z);const water=mesh(new THREE.CircleGeometry(1,40),M.water,parent);water.rotation.x=-Math.PI/2;water.scale.set(w*.47,d*.47,1);water.position.set(x,.31,z);for(let i=0;i<5;i++){const r=.09+rand()*.16;const lily=ell(parent,x+(rand()-.5)*w*.7,.34,z+(rand()-.5)*d*.7,r,.025,r,mat(i%2?'#6c8c50':'#8fa55c'));if(i===0)ell(parent,lily.position.x,.37,lily.position.z,.09,.035,.09,mat('#e2bd68'))}}
function treeProp(parent,x,z,s=1){const trunk=cylinder(parent,x,s*.7,z,s*.12,s*.18,s*1.4,M.bark,8);for(let j=0;j<3;j++){const c=mesh(new THREE.ConeGeometry(s*(.75-j*.12),s*.9,8),j%2?M.leaf2:M.leaf,parent);c.position.set(x,s*(1.3+j*.43),z)}}
function fence(parent,x,z,w,d){const post=mat('#6a533b');const rail=mat('#735d43');const pitch=2.1;for(const side of [-1,1]){const count=Math.ceil(w/pitch);for(let i=0;i<=count;i++){const xx=x-w/2+w*i/count;for(const zz of [z-d/2,z+d/2])cylinder(parent,xx,.79,zz,.075,.09,1.58,post,8)}for(const yy of [.48,1.13]){const o=box(parent,x,yy,z+side*d/2,w,.105,.11,rail);o.castShadow=false}}
 const count=Math.ceil(d/pitch);for(const side of [-1,1])for(let i=0;i<=count;i++){const zz=z-d/2+d*i/count;for(const xx of [x-w/2,x+w/2])cylinder(parent,xx,.79,zz,.075,.09,1.58,post,8)}for(const xx of [x-w/2,x+w/2])for(const yy of [.48,1.13]){const o=box(parent,xx,yy,z,d,.105,.11,rail);o.rotation.y=Math.PI/2;o.castShadow=false}}
function habitat(h,index){const g=group(scene);const floor=mesh(new THREE.PlaneGeometry(h.w,h.d),M.darkGrass,g);floor.rotation.x=-Math.PI/2;floor.position.set(h.x,.005,h.z);floor.receiveShadow=true;const x=h.x,z=h.z,w=h.w,d=h.d;
 // A shallow natural berm and habitat-specific scenery.
 for(let i=0;i<14;i++){const a=rand()*Math.PI*2,rr=.36+rand()*.65;const rock=ell(g,x+Math.cos(a)*w*.39,.3,z+Math.sin(a)*d*.39,.35*rr,.3*rr,.28*rr,M.rock,0,rand()*3,0)}
 if(h.decor==='lagoon'||h.decor==='creek'||h.decor==='falls'||h.decor==='forest')pool(g,x+.5,z+.1,w*.52,d*.42);
 if(h.decor==='savanna'){for(let i=0;i<6;i++)treeProp(g,x+(rand()-.5)*w*.65,z+(rand()-.5)*d*.55,.6+rand()*.4)}
 if(h.decor==='ridge'){for(let i=0;i<9;i++)ell(g,x+(rand()-.5)*w*.8,.45,z+(rand()-.5)*d*.72,.55+rand()*.6,.45+rand()*.5,.48,M.rock,rand()*.2,rand()*3,0)}
 if(h.decor==='jungle'||h.decor==='falls'){for(let i=0;i<7;i++)treeProp(g,x+(rand()-.5)*w*.75,z+(rand()-.5)*d*.76,.7+rand()*.45);for(let i=0;i<3;i++){const rope=mesh(new THREE.CylinderGeometry(.035,.035,3,7),M.wood,g);rope.position.set(x-4+i*3,2,z-3);rope.rotation.z=.38}if(h.decor==='falls'){const f=mesh(new THREE.BoxGeometry(.4,1.6,.18),M.water,g);f.position.set(x+4,1.05,z-4)}}
 if(h.decor==='forest'){for(let i=0;i<7;i++)treeProp(g,x+(rand()-.5)*w*.72,z+(rand()-.5)*d*.72,.85+rand()*.5);for(let i=0;i<4;i++){const log=cylinder(g,x-4+i*2,.4,z-3,.22,.22,2.7,M.bark,8);log.rotation.z=Math.PI/2}}
 if(h.decor==='creek'){for(let i=0;i<7;i++)ell(g,x+(rand()-.5)*w*.84,.24,z+(rand()-.5)*d*.78,.55,.25,.5,M.rock,0,rand()*2,0);const log=cylinder(g,x-4,.7,z-3,.19,.19,4,M.bark,8);log.rotation.z=Math.PI/2}
 if(h.name==='Elephant Valley'){for(let i=0;i<5;i++){const grass=mesh(new THREE.ConeGeometry(.16,.85,5),mat(i%2?'#b9b66f':'#9da85c'),g);grass.position.set(x-6+i*2,.42,z+4+rand()*2);grass.rotation.z=(rand()-.5)*.4}}
 if(h.name==='Tiger Forest'){const pole=cylinder(g,x+5,1.25,z+2,.16,.2,2.5,M.wood,10);for(let a=0;a<3;a++){const branch=cylinder(g,x+5,2.15,z+2,.1,.12,1.2,M.wood,8);branch.rotation.z=(a-1)*.7}for(let a=0;a<3;a++)ell(g,x+3+a*2,.55,z+4,.65,.38,.5,M.leaf)}
 if(h.name==='Lion Lookout'){for(let i=0;i<5;i++)ell(g,x-5+i*2,.4,z+3,.6,.35,.55,M.rock,0,rand()*3,0)}
 fence(g,x,z,w,d);sign(g,x,z+d/2+.5,h.name,h.species);
 // Small gold habitat medallion and animated residents.
 const n=h.name==='Elephant Valley'?2:h.name==='Hippo Lagoon'?2:2;for(let i=0;i<n;i++)makeAnimal(['elephant','rhino','hippo','tiger','lion','jaguar','wolf','bear'][index],x+(i?2:-2)+(rand()-.5)*1.3,z+(rand()-.5)*2,.72+rand()*.2);
 const marker=group(scene,x,z+d/2+1.25); // decorative habitat marker near visitor edge
}
enclosures.forEach(habitat);

// Welcoming timber entrance and a subtle panorama beyond the forest edge.
